const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;height:100%;padding:8px;display:flex;flex-direction:column;overflow:hidden;color:var(--ink);font-size:12px;line-height:1.35}\n.card *{box-sizing:border-box}\nbutton{font:inherit;cursor:pointer}\n.wrap{flex:1 1 auto;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.head{flex:none;display:flex;flex-direction:column;gap:5px;min-width:0}\n.row1{display:flex;align-items:center;gap:4px;min-width:0}\n.nav{flex:1;min-width:0;display:flex;align-items:center;gap:2px}\n.range{min-width:0;padding:0 4px;font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ink)}\nbutton.range{border:0;background:none;color:var(--accent);height:26px}\n.ib{flex:none;width:26px;height:26px;padding:0;border-radius:50%;border:1px solid var(--line);background:var(--button-paper);color:var(--ink);font-size:16px;line-height:1}\n.btn{flex:none;height:26px;padding:0 8px;border-radius:8px;border:1px solid var(--line);background:var(--button-paper);color:var(--ink);font-size:11px;white-space:nowrap}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.btn:disabled{opacity:.6}\n.add{min-width:26px;padding:0 9px}\n.add .plus{font-size:15px;line-height:1}\n.tabs{display:flex;gap:3px;padding:2px;border-radius:9px;background:var(--soft)}\n.tab{flex:1 1 0;min-width:0;height:24px;padding:0 2px;border:0;border-radius:7px;background:transparent;color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tab[aria-selected=\"true\"]{background:var(--accent);color:var(--on-accent);font-weight:700}\n.sub{display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;color:var(--muted);font-size:11px}\n.link{border:0;background:none;padding:0;color:var(--accent);font-size:11px;font-weight:600;text-decoration:underline}\n.body{flex:1 1 auto;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.list{flex:1 1 auto;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.notice{flex:none;display:flex;align-items:center;gap:6px;padding:4px 4px 4px 8px;border-radius:8px;background:var(--soft);color:var(--ink);font-size:11px}\n.notice span{flex:1;min-width:0}\n.notice .x{flex:none;width:22px;height:22px;border:0;border-radius:50%;background:transparent;color:var(--ink);font-size:14px;line-height:1;padding:0}\n.day{flex:none;display:flex;flex-direction:column;gap:5px;min-width:0}\n.dayh{display:flex;align-items:center;gap:5px;min-width:0}\n.dw{font-weight:700;font-size:12px}\n.dd{color:var(--muted);font-size:11px}\n.day.today .dw{color:var(--accent)}\n.none{color:var(--muted);font-size:11px}\n.addday{margin-left:auto;flex:none;width:24px;height:24px;padding:0;border-radius:50%;border:1px solid var(--line);background:var(--button-paper);color:var(--ink);font-size:14px;line-height:1}\n.day.empty{opacity:.85}\n.items{display:grid;grid-template-columns:minmax(0,1fr);gap:6px;min-width:0}\n.post{min-width:0;display:flex;flex-direction:column;gap:5px;padding:6px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.post.pub{background:var(--paper)}\n.post.pub .tt{color:var(--muted)}\n.ptop{display:flex;align-items:flex-start;gap:5px;min-width:0}\n.ptitle{flex:1 1 0;min-width:0;min-height:26px;margin:0;padding:0;border:0;background:none;text-align:left;color:var(--ink)}\n.tl{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;font-size:13px;font-weight:600;line-height:1.35;word-break:break-word}\n.tag{display:inline-block;margin-right:4px;padding:0 5px;border-radius:6px;font-size:10px;font-weight:600;line-height:1.5;vertical-align:1px}\n.tag.od{background:var(--ink);color:var(--paper)}\n.tag.pd{background:var(--soft);color:var(--ink)}\n.tag.now{background:var(--accent);color:var(--on-accent);margin:0}\n.pubb{flex:none}\n.pmeta{display:flex;align-items:center;gap:5px;min-width:0}\n.plat{flex:0 1 auto;max-width:44%;padding:2px 7px;border-radius:999px;background:var(--soft);color:var(--ink);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.datein{flex:1 1 0;min-width:0;height:26px;padding:0 4px;border:1px solid var(--line);border-radius:7px;background:var(--paper);color:var(--ink);font:inherit;font-size:11px}\n.ticks{display:flex;gap:3px}\n.tick{flex:1 1 0;min-width:0;height:28px;padding:0 2px;border:1px solid var(--line);border-radius:7px;background:var(--paper);color:var(--ink);font-size:11px;white-space:nowrap;display:flex;align-items:center;justify-content:center;gap:1px}\n.tick.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:700}\n.tick.on::before{content:\"\u2713\";font-size:10px}\n.ask{display:flex;flex-wrap:wrap;align-items:center;gap:4px;padding-top:5px;border-top:1px dashed var(--line);font-size:11px}\n.ask span{flex:1 1 100%}\n.empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;padding:14px 6px;text-align:center;color:var(--muted)}\n.empty .btn{height:30px}\n\n.form{flex:1 1 auto;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.fhead{flex:none;display:flex;align-items:center;gap:6px}\n.fh{font-size:13px;font-weight:700}\n.fbody{flex:1 1 auto;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0;color:var(--muted);font-size:11px}\n.fld input{width:100%;height:30px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);font:inherit;font-size:13px}\n.chips{display:flex;flex-wrap:wrap;gap:4px}\n.chip{height:24px;padding:0 9px;border-radius:999px;border:1px solid var(--line);background:var(--soft);color:var(--ink);font-size:11px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.err{color:var(--ink);font-size:12px;font-weight:700}\n.ffoot{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:5px}\n.ffoot .btn{flex:1 1 0;height:30px}\n.asktxt{flex:1 1 100%;color:var(--ink);font-size:11px}\n\n.card[data-size=\"3x3\"] .sub,.card[data-size=\"6x3\"] .sub{display:none}\n.card[data-size=\"3x3\"] .add .lbl,.card[data-size=\"3x6\"] .add .lbl{display:none}\n.card[data-size=\"3x3\"] .add,.card[data-size=\"3x6\"] .add{width:28px;height:28px;padding:0}\n.card[data-size=\"6x3\"] .wrap{flex-direction:row;gap:8px}\n.card[data-size=\"6x3\"] .head{flex:none;width:118px;overflow-y:auto}\n.card[data-size=\"6x3\"] .row1{flex-direction:column;align-items:stretch;gap:5px}\n.card[data-size=\"6x3\"] .nav{justify-content:space-between}\n.card[data-size=\"6x3\"] .add{height:28px}\n.card[data-size=\"6x3\"] .tabs{flex-direction:column}\n.card[data-size=\"6x3\"] .fbody{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-content:start;gap:6px 8px}\n.card[data-size=\"6x3\"] .err{grid-column:1 / -1}\n.card[data-size=\"6x6\"] .items{grid-template-columns:repeat(2,minmax(0,1fr))}\n.card[data-size=\"6x6\"] .row1{gap:8px}\n.card[data-size=\"6x6\"] .tabs{align-self:stretch}\n.card[data-size=\"6x6\"] .wrap{gap:8px}\n";
var CK=[['copy','文案'],['image','配图'],['cover','封面'],['proof','校对']];
var WD=['周日','周一','周二','周三','周四','周五','周六'];
function pad(n){return n<10?'0'+n:''+n;}
function fmtD(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());}
function parseD(s){var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');if(!m)return null;var d=new Date(+m[1],+m[2]-1,+m[3]);return fmtD(d)===s?d:null;}
function addDays(s,n){var d=parseD(s);d.setDate(d.getDate()+n);return fmtD(d);}
function mondayOf(s){var d=parseD(s);d.setDate(d.getDate()-((d.getDay()+6)%7));return fmtD(d);}
function md(s){var d=parseD(s);return d?(d.getMonth()+1)+'/'+d.getDate():'';}
function wd(s){var d=parseD(s);return d?WD[d.getDay()]:'';}
function postsOf(s){return s&&Array.isArray(s.posts)?s.posts:[];}
function isOn(p,k){return !!(p.checks&&p.checks[k]);}
function doneN(p){var n=0;CK.forEach(function(c){if(isOn(p,c[0]))n++;});return n;}
function byDate(a,b){return a.date<b.date?-1:a.date>b.date?1:0;}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  const today=day();
  if(!ui.tab)ui.tab='week';
  if(!ui.weekStart)ui.weekStart=mondayOf(today);
  if(!ui.view)ui.view='list';
  const all=postsOf(state);
  const short=size==='3x3'||size==='6x3';
  let timer=null;

  function fail(){ui.notice='保存失败，请重试';ui.saving=false;redraw();}
  function save(fn,notice){
    ui.notice=notice||'';
    return update(function(s){return Object.assign({},s,{posts:fn(postsOf(s))});}).catch(fail);
  }
  function go(patch){ui.notice='';ui.scroll=0;ui.confirm=null;Object.assign(ui,patch);redraw();}
  function setP(id,fn,notice){
    return save(function(list){return list.map(function(p){return p.id===id?fn(p):p;});},notice);
  }
  function toggle(id,k){
    setP(id,function(p){var c=Object.assign({},p.checks);c[k]=!c[k];return Object.assign({},p,{checks:c});});
  }
  function doPublish(id){
    ui.confirm=null;
    setP(id,function(p){return Object.assign({},p,{published:true,publishedAt:day()});});
  }
  function unpublish(id){
    setP(id,function(p){return Object.assign({},p,{published:false,publishedAt:null});});
  }
  function tryPublish(p){
    if(doneN(p)<4){ui.confirm=p.id;redraw();}else{doPublish(p.id);}
  }
  function setDate(p,v){
    if(!parseD(v)){redraw();return;}
    var note='';
    if(ui.tab==='week'&&mondayOf(v)!==ui.weekStart)note='「'+p.title+'」已改到 '+wd(v)+' '+md(v)+'，不在当前这一周';
    setP(p.id,function(q){return Object.assign({},q,{date:v});},note);
  }
  function openAdd(date){
    var d=date||(mondayOf(today)===ui.weekStart?today:ui.weekStart);
    go({view:'form',draft:{title:'',platform:'',date:d,error:''},delAsk:false});
  }
  function openEdit(p){
    go({view:'form',draft:{id:p.id,title:p.title,platform:p.platform||'',date:p.date,error:''},delAsk:false});
  }
  function platforms(){
    var seen=[];
    all.forEach(function(p){var n=(p.platform||'').trim();if(n&&seen.indexOf(n)<0)seen.push(n);});
    return seen.slice(0,8);
  }


  function postEl(p){
    const od=!p.published&&p.date<today;
    const n=doneN(p);
    const tl=el('span',{class:'tl'});
    if(od)tl.append(el('span',{class:'tag od'},'逾期'));
    if(p.published)tl.append(el('span',{class:'tag pd'},'已发'+(p.publishedAt?' '+md(p.publishedAt):'')));
    tl.append(el('span',{class:'tt'},p.title));
    const t=el('button',{type:'button',class:'ptitle','aria-label':'编辑：'+p.title,onclick:function(){openEdit(p);}},tl);
    const pub=p.published
      ?el('button',{type:'button',class:'btn pubb',onclick:function(){unpublish(p.id);}},'撤回')
      :el('button',{type:'button',class:'btn primary pubb',onclick:function(){tryPublish(p);}},'标记已发');
    const dateIn=el('input',{type:'date',class:'datein',value:p.date,'aria-label':'计划发布日期',onchange:function(e){setDate(p,e.target.value);}});
    const meta=el('div',{class:'pmeta'},el('span',{class:'plat'},p.platform||'未填平台'),dateIn);
    const ticks=el('div',{class:'ticks',role:'group','aria-label':'制作进度，已完成'+n+'项，共4项'});
    CK.forEach(function(c){
      const on=isOn(p,c[0]);
      ticks.append(el('button',{type:'button',class:'tick'+(on?' on':''),role:'checkbox','aria-checked':on?'true':'false',onclick:function(){toggle(p.id,c[0]);}},c[1]));
    });
    const card=el('article',{class:'post'+(p.published?' pub':'')},el('div',{class:'ptop'},t,pub),meta,ticks);
    if(ui.confirm===p.id&&!p.published&&n<4){
      card.append(el('div',{class:'ask',role:'alert'},
        el('span',{},'还有 '+(4-n)+' 项没勾，仍标记已发？'),
        el('button',{type:'button',class:'btn primary',onclick:function(){doPublish(p.id);}},'仍标记'),
        el('button',{type:'button',class:'btn',onclick:function(){ui.confirm=null;redraw();}},'再看看')));
    }
    return card;
  }

  function emptyBox(msg,label,fn){
    const b=el('div',{class:'empty'},el('div',{class:'em'},msg));
    if(label)b.append(el('button',{type:'button',class:'btn primary',onclick:fn},label));
    return b;
  }

  function itemsGrid(arr){
    const g=el('div',{class:'items'});
    arr.forEach(function(p){g.append(postEl(p));});
    return g;
  }

  function buildList(){
    const list=el('div',{class:'list'});
    list.addEventListener('scroll',function(){ui.scroll=list.scrollTop;});
    if(ui.tab==='week'){
      const ws=ui.weekStart,we=addDays(ws,6);
      const wk=all.filter(function(p){return p.date>=ws&&p.date<=we;});
      if(!wk.length){
        list.append(emptyBox(all.length?'这周还没有安排':'还没有图文，先添加第一篇','添加图文',function(){openAdd();}));
        return list;
      }
      for(let i=0;i<7;i++){
        const d=addDays(ws,i);
        const items=wk.filter(function(p){return p.date===d;});
        if(!items.length&&short)continue;
        const sec=el('section',{class:'day'+(d===today?' today':'')+(items.length?'':' empty')});
        const h=el('div',{class:'dayh'},el('span',{class:'dw'},wd(d)),el('span',{class:'dd'},md(d)));
        if(d===today)h.append(el('span',{class:'tag now'},'今天'));
        if(!items.length)h.append(el('span',{class:'none'},'暂无安排'));
        h.append(el('button',{type:'button',class:'addday','aria-label':'在'+wd(d)+' '+md(d)+'添加图文',onclick:function(){openAdd(d);}},'+'));
        sec.append(h);
        if(items.length)sec.append(itemsGrid(items));
        list.append(sec);
      }
      return list;
    }
    const isDone=ui.tab==='done';
    const arr=all.filter(function(p){return !!p.published===isDone;});
    if(isDone){
      arr.sort(function(a,b){var x=a.publishedAt||a.date,y=b.publishedAt||b.date;return x<y?1:x>y?-1:0;});
    }else{
      arr.sort(byDate);
    }
    if(!arr.length){
      list.append(emptyBox(isDone?'还没有标记已发的图文':(all.length?'没有待发的图文':'还没有图文，先添加第一篇'),all.length?'':'添加图文',all.length?null:function(){openAdd();}));
      return list;
    }
    list.append(itemsGrid(arr));
    return list;
  }

  function buildHead(){
    const ws=ui.weekStart,we=addDays(ws,6),cur=mondayOf(today);
    const todoN=all.filter(function(p){return !p.published;}).length;
    const pubN=all.length-todoN;
    const overdue=all.filter(function(p){return !p.published&&p.date<today;}).length;
    const head=el('div',{class:'head'});
    const row=el('div',{class:'row1'});
    if(ui.tab==='week'){
      const y=parseD(ws).getFullYear();
      const yr=y!==parseD(today).getFullYear()?y+'年 ':'';
      const txt=yr+md(ws)+'–'+md(we);
      const nav=el('div',{class:'nav'});
      nav.append(el('button',{type:'button',class:'ib','aria-label':'上一周',onclick:function(){go({weekStart:addDays(ws,-7)});}},'‹'));
      if(ws===cur){
        nav.append(el('span',{class:'range','aria-label':'本周 '+txt},txt));
      }else{
        nav.append(el('button',{type:'button',class:'range back','aria-label':'回到本周',onclick:function(){go({weekStart:cur});}},txt+' ↺'));
      }
      nav.append(el('button',{type:'button',class:'ib','aria-label':'下一周',onclick:function(){go({weekStart:addDays(ws,7)});}},'›'));
      row.append(nav);
    }else{
      row.append(el('div',{class:'nav'},el('span',{class:'range'},ui.tab==='done'?'已发 '+pubN+' 篇':'待发 '+todoN+' 篇')));
    }
    row.append(el('button',{type:'button',class:'btn primary add','aria-label':'添加图文',onclick:function(){openAdd();}},el('span',{class:'plus'},'+'),el('span',{class:'lbl'},' 添加')));
    head.append(row);
    const tabs=el('div',{class:'tabs',role:'tablist'});
    [['week','周排期'],['todo','待发 '+todoN],['done','已发布 '+pubN]].forEach(function(t){
      tabs.append(el('button',{type:'button',role:'tab',class:'tab','aria-selected':ui.tab===t[0]?'true':'false',onclick:function(){if(ui.tab!==t[0])go({tab:t[0]});}},t[1]));
    });
    head.append(tabs);
    const sub=el('div',{class:'sub'});
    if(ui.tab==='week'){
      const wk=all.filter(function(p){return p.date>=ws&&p.date<=we;});
      const wp=wk.filter(function(p){return p.published;}).length;
      sub.append(el('span',{},(ws===cur?'本周':'该周')+' '+wk.length+' 篇 · 已发 '+wp+' · 待发 '+(wk.length-wp)));
      if(overdue)sub.append(el('button',{type:'button',class:'link',onclick:function(){go({tab:'todo'});}},overdue+' 篇已逾期 ›'));
    }else if(ui.tab==='todo'){
      sub.append(el('span',{},'按计划日期从早到晚'));
    }else{
      sub.append(el('span',{},'最近发布的在前'));
    }
    head.append(sub);
    return head;
  }


  function saveForm(){
    const d=ui.draft;
    if(!d||ui.saving)return;
    const title=(d.title||'').trim(),platform=(d.platform||'').trim();
    if(!title){d.error='请填写标题';redraw();return;}
    if(!platform){d.error='请填写发布平台';redraw();return;}
    if(!parseD(d.date)){d.error='请选择计划发布日期';redraw();return;}
    d.error='';
    ui.saving=true;
    const date=d.date;
    const id=d.id||uid();
    const adding=!d.id;
    const next=Object.assign({},ui,{view:'list',draft:null,saving:false,delAsk:false,scroll:0,notice:'',confirm:null,
      tab:(adding&&ui.tab==='done')?'week':ui.tab,
      weekStart:(adding||ui.tab==='week')?mondayOf(date):ui.weekStart});
    commit(function(s){
      const list=postsOf(s);
      let out;
      if(adding){
        out=list.concat([{id:id,title:title,platform:platform,date:date,checks:{copy:false,image:false,cover:false,proof:false},published:false,publishedAt:null,createdAt:day()}]);
      }else{
        out=list.map(function(p){return p.id===id?Object.assign({},p,{title:title,platform:platform,date:date}):p;});
      }
      return Object.assign({},s,{posts:out});
    },next).catch(function(){
      ui.saving=false;
      d.error='保存失败，请重试';
      redraw();
    });
  }

  function deletePost(){
    const d=ui.draft;
    if(!d||!d.id||ui.saving)return;
    ui.saving=true;
    const id=d.id;
    commit(function(s){
      return Object.assign({},s,{posts:postsOf(s).filter(function(p){return p.id!==id;})});
    },Object.assign({},ui,{view:'list',draft:null,saving:false,delAsk:false,scroll:0,notice:'',confirm:null})).catch(function(){
      ui.saving=false;
      d.error='删除失败，请重试';
      redraw();
    });
  }

  function buildForm(){
    const d=ui.draft;
    const editing=!!d.id;
    function inp(key,ph,type){
      return el('input',{type:type||'text',value:d[key]||'',placeholder:ph||'',
        oninput:function(e){d[key]=e.target.value;},
        onchange:function(e){d[key]=e.target.value;},
        onkeydown:function(e){if(e.key==='Enter')saveForm();}});
    }
    const pf=el('label',{class:'fld'},el('span',{},'发布平台'),inp('platform','例如：公众号、小红书'));
    const plats=platforms();
    if(plats.length){
      const chips=el('div',{class:'chips'});
      plats.forEach(function(n){
